-- ----------------------------
-- Table structure for `papers`
-- ----------------------------
DROP TABLE IF EXISTS `papers`;
CREATE TABLE `papers` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `participant_id` int(10) unsigned DEFAULT NULL COMMENT '參加者ID',
  `season_id` int(10) unsigned NOT NULL COMMENT '賽季ID',
  `number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '試題參考編號',
  `difficulty` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '答題卷難度',
  `status` enum('creating','created','assigned','processing','finished','cancelled','voided') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'creating' COMMENT '答題卷狀態',
  `score` smallint(6) NOT NULL DEFAULT '0' COMMENT '得分',
  `started_at` timestamp NULL DEFAULT NULL COMMENT '開始時間',
  `finished_at` timestamp NULL DEFAULT NULL COMMENT '開始時間',
  `seconds_used` smallint(6) NOT NULL DEFAULT '0' COMMENT '完成所需秒數',
  `questions_answered` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '完成的題目數量',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `papers_number_unique` (`number`),
  KEY `papers_participant_id_foreign` (`participant_id`),
  KEY `papers_season_id_foreign` (`season_id`),
  CONSTRAINT `papers_participant_id_foreign` FOREIGN KEY (`participant_id`) REFERENCES `participants` (`id`),
  CONSTRAINT `papers_season_id_foreign` FOREIGN KEY (`season_id`) REFERENCES `seasons` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=293 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of papers
-- ----------------------------

-- ----------------------------
-- Table structure for `paper_questions`
-- ----------------------------
DROP TABLE IF EXISTS `paper_questions`;
CREATE TABLE `paper_questions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `paper_id` int(10) unsigned NOT NULL COMMENT '答題卷ID',
  `question_id` int(10) unsigned NOT NULL COMMENT '賽題ID',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT '可選擇答案',
  `answer` text COLLATE utf8mb4_unicode_ci COMMENT '參加者答案',
  `correct` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否正確',
  `score` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '分數',
  `started_at` timestamp NULL DEFAULT NULL COMMENT '答題開始時間',
  `finished_at` timestamp NULL DEFAULT NULL COMMENT '答題結束時間',
  `seconds_used` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '答題耗時（秒)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `paper_questions_paper_id_foreign` (`paper_id`),
  KEY `paper_questions_question_id_foreign` (`question_id`),
  CONSTRAINT `paper_questions_paper_id_foreign` FOREIGN KEY (`paper_id`) REFERENCES `papers` (`id`),
  CONSTRAINT `paper_questions_question_id_foreign` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8731 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of paper_questions
-- ----------------------------

