  `user_id` int(10) unsigned DEFAULT NULL COMMENT '用戶ID',
  `school_id` int(10) unsigned DEFAULT NULL COMMENT '用戶所屬學校ID',
  `school_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '學校名稱',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '參加者姓名',
  `grade` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '參加者年級',
  `class` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '參加者班級',
  `organization_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '參加者所屬機構ID',
  `organization_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '機構名稱',
  `department` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '機構部門',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `paper_id` int(8) unsigned DEFAULT NULL COMMENT '參與者當前分配的試卷id',
  PRIMARY KEY (`id`),
  KEY `participants_school_id_foreign` (`school_id`),
  CONSTRAINT `participants_school_id_foreign` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of participants
