-- ----------------------------
-- Table structure for `posts`
-- ----------------------------
DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(10) unsigned DEFAULT NULL COMMENT '分类id',
  `user_id` int(11) DEFAULT NULL,
  `title` varchar(225) NOT NULL COMMENT '  标题',
  `slug` varchar(100) DEFAULT NULL,
  `excerpt` text COMMENT '    摘要',
  `content` text COMMENT ' 正文',
  `cover_image` varchar(100) DEFAULT NULL COMMENT '  封面图',
  `published_at` timestamp NULL DEFAULT NULL COMMENT '  发布时间',
  `published` int(11) DEFAULT NULL COMMENT '    是否发布',
  `hits` int(11) DEFAULT NULL COMMENT ' 点击',
  `last_modify_user` varchar(45) DEFAULT NULL COMMENT '最后修改人',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `featured` tinyint(2) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COMMENT='posts资讯表 ';

-- ----------------------------
-- Records of posts
-- ----------------------------

-- ----------------------------
-- Table structure for `questions`
-- ----------------------------
DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(10) unsigned DEFAULT NULL COMMENT '題目分類ID',
  `scope_id` int(10) unsigned DEFAULT NULL COMMENT '範籌分類ID',
  `user_id` int(10) unsigned DEFAULT NULL COMMENT '出題者ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '題目',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '簡介',
  `level` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '難度',
  `hit` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '出題命中數',
  `correct_rate` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '答題正確率',
  `reference` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `questions_category_id_foreign` (`category_id`),
  KEY `questions_scope_id_foreign` (`scope_id`),
  CONSTRAINT `questions_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `question_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_scope_id_foreign` FOREIGN KEY (`scope_id`) REFERENCES `question_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of questions
-- ----------------------------

-- ----------------------------
-- Table structure for `question_categories`
-- ----------------------------
DROP TABLE IF EXISTS `question_categories`;
CREATE TABLE `question_categories` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分類名稱',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `question_categories_name_unique` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of question_categories
-- ----------------------------

-- ----------------------------
-- Table structure for `references`
-- ----------------------------
DROP TABLE IF EXISTS `references`;
CREATE TABLE `references` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `cover_image` varchar(255) DEFAULT NULL COMMENT '封面图',
  `desc` varchar(255) DEFAULT NULL COMMENT ' 简介',
  `link` varchar(255) DEFAULT NULL COMMENT ' 连接',
  `status` tinyint(2) DEFAULT '0' COMMENT '  是否发布',
  `created_at` timestamp NULL DEFAULT NULL COMMENT ' 添加时间',
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `author` varchar(125) DEFAULT NULL COMMENT 'author',
  `hits` int(11) DEFAULT '0',
  `content` text NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COMMENT='参考资料表';

-- ----------------------------
-- Records of references
-- ----------------------------

-- ----------------------------
-- Table structure for `schools`
-- ----------------------------
DROP TABLE IF EXISTS `schools`;
CREATE TABLE `schools` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '學校名稱',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '學校地址',
  `contact` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '聯絡人',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聯絡電郵',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聯絡電話',
  `fax` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '傳真號碼',
  `approved` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已審核',
  `student` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '學生人數',
  `expected_participant` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '預期參加學生人數',
  `actual_participant` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '實際參加學生人數',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '參賽代碼',
  `teaching_subject` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任教科目',
  `contact2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `teaching_subject2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任教科目2',
  `email2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '郵箱2',
  `phone2` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of schools
-- ----------------------------

-- ----------------------------
-- Table structure for `scopes`
-- ----------------------------
DROP TABLE IF EXISTS `scopes`;
CREATE TABLE `scopes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `scopes_name_unique` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of scopes
-- ----------------------------

-- ----------------------------
-- Table structure for `seasons`
-- ----------------------------
DROP TABLE IF EXISTS `seasons`;
CREATE TABLE `seasons` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '賽季名稱',
  `status` enum('ready','open','closed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ready' COMMENT '賽季狀態',
  `start_at` timestamp NULL DEFAULT NULL COMMENT '比賽開始時間',
  `end_at` timestamp NULL DEFAULT NULL COMMENT '比賽結束時間',
  `is_intercollegiate` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否校際賽',
  `times_limit` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '每個用戶可參加次數',
  `time_interval` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '次數之間的間隔（分鐘）',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of seasons
-- ----------------------------

-- ----------------------------
-- Table structure for `sponsors`
-- ----------------------------
DROP TABLE IF EXISTS `sponsors`;
CREATE TABLE `sponsors` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '名称',
  `parent_id` int(11) DEFAULT '0' COMMENT '  上级id',
  `order` int(11) DEFAULT '0' COMMENT ' 排序',
  `logo` varchar(255) DEFAULT NULL,
  `status` tinyint(2) DEFAULT '0' COMMENT '  状态',
  `link` varchar(255) DEFAULT NULL COMMENT ' 链接',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='赞助商表';

