INSERT INTO `competition_info` VALUES ('3', '賽事介紹', '1', '3', '<p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">根据引渡程序，美国自临时逮捕之日起有60天时间向加提供支持指控的文件。加政府的一个法律团队必须在30天后决定是否引渡。被告可向上诉法院申诉。如不服上诉法院裁定可再上诉到加拿大联邦法院。最终，加拿大司法部长将决定是否把某人引渡到美国。<span class=\"bjh-br\"></span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这些来来回回可能正好赶上美国国会讨论修订后的美加墨自由贸易协定，还将与美中贸易战的停火期重合。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><img style=\"width: 640px;\" src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/GTXfEAHtiAL6FGK4SOKVS59M2BCEW3vFmgGtnlcq.jpeg\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">加拿大贸易部长吉姆·卡尔说：“我们知道未来的发展方向，正在采取必要举措保障这个未来。”他所说的未来在中国。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">另据加拿大《环球邮报》网站12月6日报道，无论加拿大喜欢与否，加拿大现在都成了中美全球支配地位之争的关键角色，而这场争夺正在危险地升级。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">加拿大眼下处于两难境地：不能不冒犯中国人，除非为了安抚中国人而去大大冒犯美国人。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">中美关系处于低谷，这对加拿大来说很糟，对世界来说也很糟。讽刺之处在于，在温哥华逮捕孟晚舟，加拿大出了一把力，让情况变得更糟。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">此外据加拿大《温哥华星报》网站12月8日报道，前驻华大使、现任加拿大艾伯塔大学中国研究所研究员的居伊·圣-雅克说，温哥华一家法院正在审理孟晚舟的保释申请，加拿大身陷两难境地，一边是与美国的引渡条约，另一边是中国的科技巨头。他说，加拿大现在很容易遭到报复。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">圣-雅克说：“我们对中国来说并不是一个非常重要的国家。我担心他们会对我们施加很大压力。”</span></p>', '1', '2018-10-31 13:55:22', '2018-12-11 18:59:22', '2018-10-31 13:57:20');
INSERT INTO `competition_info` VALUES ('4', '流程', '1', '4', '<p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">立即撤销逮捕令！</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">12月8日和9日，是北京今年入冬以来最寒冷的一个周末。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这两天，中国外交部副部长乐玉成格外忙碌。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">由他出面代表中国政府两次紧急召见驻华大使，后来被媒体纷纷以“重磅”消息密集报道。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">被召见人，则分别是加拿大驻华大使麦家廉和美国驻华大使布兰斯塔德。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><img style=\"width: 600px;\" src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/hWlPAWXcfM5eqwYYhBCCJlt7p78rAH79U0ndacsf.jpeg\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">从外交部网站的消息中，小锐发现，在召见两位大使时，乐玉成副部长均提到了下列8个字：严正交涉，强烈抗议。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">在对美加拘押孟晚舟女士事件的定性上，乐玉成副部长两次亦都作出如下表态：“严重侵犯中国公民的合法、正当权益”，“性质极其恶劣”。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">值得注意的是，在中方两次紧急召见的表态中，处处可见强烈的警示意味。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">8日，中方强烈敦促加方立即释放被拘押人员，切实保障当事人的合法、正当权益。否则必将造成严重后果，加方要为此承担全部责任。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">9日，乐玉成要求美方，立即采取措施纠正错误做法，撤销对中国公民的逮捕令。中方将视美方行动作出进一步反应。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">用词不可谓不重，警告意味不可谓不清晰。</span></p>', '1', '2018-10-31 13:55:22', '2018-12-11 19:00:07', '2018-10-31 13:57:20');
INSERT INTO `competition_info` VALUES ('5', '範圍', '1', '5', '<p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">立即撤销逮捕令！</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">12月8日和9日，是北京今年入冬以来最寒冷的一个周末。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这两天，中国外交部副部长乐玉成格外忙碌。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">由他出面代表中国政府两次紧急召见驻华大使，后来被媒体纷纷以“重磅”消息密集报道。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">被召见人，则分别是加拿大驻华大使麦家廉和美国驻华大使布兰斯塔德。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><img style=\"width: 600px;\" src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/nBNmGUcjlCIYkVxd0beBx6uHbpq8C1AJePuzeWaI.jpeg\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">从外交部网站的消息中，小锐发现，在召见两位大使时，乐玉成副部长均提到了下列8个字：严正交涉，强烈抗议。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">在对美加拘押孟晚舟女士事件的定性上，乐玉成副部长两次亦都作出如下表态：“严重侵犯中国公民的合法、正当权益”，“性质极其恶劣”。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">值得注意的是，在中方两次紧急召见的表态中，处处可见强烈的警示意味。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">8日，中方强烈敦促加方立即释放被拘押人员，切实保障当事人的合法、正当权益。否则必将造成严重后果，加方要为此承担全部责任。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">9日，乐玉成要求美方，立即采取措施纠正错误做法，撤销对中国公民的逮捕令。中方将视美方行动作出进一步反应。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">用词不可谓不重，警告意味不可谓不清晰。</span></p>', '1', '2018-10-31 13:55:22', '2018-12-11 19:00:53', '2018-10-31 13:57:20');
