INSERT INTO `global` VALUES ('1', 'info@looop.hk', 'info@looop.hk', 'info@looop.hk', 'info@looop.hk', 'active', 'LOOOP MEDIA LTD.', 'LOOOP.HK', 'LOOOP', 'authors/1d48d4b1ce1aa94888e923ac464bfbd4.png', '/img/logo_crecra.png', '', '85228041301', '85228041301', '九龍荔枝角長順街7號西頓中心33樓3301-3, 3305-7室', 'China', 'Hong Kong', '', 'http://mmm.yilianfun.cn', 'https://www.facebook.com/speakout.hk', 'https://www.facebook.com/speakout.hk', '', null, null, 'LOOOP.HK', '<p style=\"padding: 0px; color: rgb(68, 68, 68); font-family:; margin-bottom: 25px;\" 252);\"=\"\" 252,=\"\" rgb(252,=\"\" sans-serif;=\"\" sans\",=\"\" open=\"\">承印人: 圈傳媒有限公司</p><p style=\"padding: 0px; color: rgb(68, 68, 68); font-family:; margin-bottom: 25px;\" 252);\"=\"\" 252,=\"\" rgb(252,=\"\" sans-serif;=\"\" sans\",=\"\" open=\"\">承印地址: 九龍荔枝角長順街7號西頓中心33樓3301-3, 3305-7室</p><p style=\"padding: 0px; color: rgb(68, 68, 68); font-family:; margin-bottom: 25px;\" 252);\"=\"\" 252,=\"\" rgb(252,=\"\" sans-serif;=\"\" sans\",=\"\" open=\"\"> </p><p style=\"padding: 0px; color: rgb(68, 68, 68); font-family:; margin-bottom: 25px;\" 252);\"=\"\" 252,=\"\" rgb(252,=\"\" sans-serif;=\"\" sans\",=\"\" open=\"\">Printer : Looop Media Limited</p><p style=\"padding: 0px; color: rgb(68, 68, 68); font-family:; margin-bottom: 25px;\" 252);\"=\"\" 252,=\"\" rgb(252,=\"\" sans-serif;=\"\" sans\",=\"\" open=\"\">Printer Address : Office No. 3301-3, 3305-7 33/F Saxon Tower, 7 Cheung Shun Street, Lai Chi Kok, Kowloon</p>', '<p>Returns Our policy lasts 30 days. If 30 days have gone by since your purchase, unfortunately we can&rsquo;t offer you a refund or exchange. To be eligible for a return, your item must be unused and in the same condition that you received it. It must also be in the original packaging. Several types of goods are exempt from being returned. Perishable goods such as food, flowers, newspapers or magazines cannot be returned. We also do not accept products that are intimate or sanitary goods, hazardous materials, or flammable liquids or gases. Additional non-returnable items: Gift cards Downloadable software products Some health and personal care items To complete your return, we require a receipt or proof of purchase. Please do not send your purchase back to the manufacturer. There are certain situations where only partial refunds are granted: (if applicable) Book with obvious signs of use CD, DVD, VHS tape, software, video game, cassette tape, or vinyl record that has been opened. Any item not in its original condition, is damaged or missing parts for reasons not due to our error. Any item that is returned more than 30 days after delivery Refunds (if applicable) Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund. If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days. Late or missing refunds (if applicable) If you haven&rsquo;t received a refund yet, first check your bank account again. Then contact your credit card global, it may take some time before your refund is officially posted. Next contact your bank. There is often some processing time before a refund is posted. If you&rsquo;ve done all of this and you still have not received your refund yet, please contact us at [ [ email@email.com ] ]. Sale items (if applicable) Only regular priced items may be refunded, unfortunately sale items cannot be refunded. Exchanges (if applicable) We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at [ [ email@email.com ] ] and send your item to: [ [ Address ] ] [ [ City ] ] [ [ State ] ] [ [ Country ] ] [ [ PostCode ] ]. Gifts If the item was marked as a gift when purchased and shipped directly to you, you&rsquo;ll receive a gift credit for the value of your return. Once the returned item is received, a gift certificate will be mailed to you. If the item wasn&rsquo;t marked as a gift when purchased, or the gift giver had the order shipped to themselves to give to you later, we will send a refund to the gift giver and he will find out about your return. Shipping To return your product, you should mail your product to: [ [ Address ] ] [ [ City ] ] [ [ State ] ] [ [ Country ] ] [ [ PostCode ] ]. You will be responsible for paying for your own shipping costs for returning your item. Shipping costs are non-refundable. If you receive a refund, the cost of return shipping will be deducted from your refund. Depending on where you live, the time it may take for your exchanged product to reach you, may vary. If you are shipping an item over $75, you should consider using a trackable shipping service or purchasing shipping insurance. We don&rsquo;t guarantee that we will receive your returned item.</p>', '<p>PRIVACY STATEMENT</p>', '<p>TERMS OF SERVICE</p>', 'AIzaSyCutQnEgrqX8W2X-nBCYB7-CbsTC-LlRMw', '2017-03-29 23:10:15', '2018-12-11 19:35:55', null, null, '港人講地', 'yk.yau@looop.hk', 'yk.yau@looop.hk', '5', '15', '30', '0', '31', '1', 'http://looop.hk/%E9%97%9C%E6%96%BC%E6%88%91%E5%80%91', 'http://looop.hk/%E9%97%9C%E6%96%BC%E6%88%91%E5%80%91', 'http://looop.hk/%E9%97%9C%E6%96%BC%E6%88%91%E5%80%91', 'sponsor/1afa9a7aa92739734cdcecfb74c6112a.jpg', 'sponsor/2e89e5f44ef119bc9571ded8a39c3b13.jpg', 'http://www.baidu.com', 'authors/ad48f01b594f2ef3a2f6c3ec7595c83e.png', 'authors/24c86cdb290cff056686e85436fad0b5.png', '1', '1');
