INSERT INTO `posts` VALUES ('10', '1', '1', 'SpreadJS纯前端表格控件，可嵌入应用开发的在线Excel', 'SpreadJS纯前端表格控件-可嵌入应用开发的在线Excel', '研讨会现场。澎湃新闻记者 于潇清 摄 中国国务委员兼外交部长王毅在12月11日的演讲中谈及中国公民海外安全问题时表示，“我们时刻关心每一位在海外中国同胞的安危冷暖，对于任何肆意侵害中国公民正当权益的霸凌行径，...', '<p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">研讨会现场。澎湃新闻记者 于潇清 摄</span></p><p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><img style=\"width: 640px;\" src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/S41ZSdWyFldCcOg5p5w6ugZ2N7ZjpiUMYCUQCs54.jpeg\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">中国国务委员兼外交部长王毅在12月11日的演讲中谈及中国公民海外安全问题时表示，“我们时刻关心每一位在海外中国同胞的安危冷暖，对于任何肆意侵害中国公民正当权益的霸凌行径，中方绝不会坐视不管，将全力中国维护公民的合法权利，还世界一份公道 正义。”</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">2018年12月11日，王毅出席由中国国际问题研究院及中国国际问题研究基金会联合主办的“国际形势新变化与中国外交新征程——2018年国际形势与中国外交研讨会”，并发表主旨演讲。</span></p>', 'articles/cover/20181211/abf1080f440115f106e33f2125cf2206.jpg', '2018-12-11 18:15:16', '1', null, null, '2018-12-11 18:13:28', '2018-12-11 19:02:35', null, '0');
INSERT INTO `posts` VALUES ('11', '1', '1', '超50万VC++源码: 大型组态工控、电力仿真CAD与GIS源码库！', '超50万VC-源码--大型组态工控-电力仿真CAD与GIS源码库-', '反倒是規定發給對方告訴我說根据引渡程序，美国自临时逮捕之日起有60天时间向加提供支持指控的文件。加政府的一个法律团队必须在30天后决定是否引渡。被告可向上诉法院申诉。如不服上诉法院裁定可再上诉到加拿大联邦...', '<p>反倒是規定發給對方告訴我說<span style=\"color: rgb(51, 51, 51); font-family: arial; font-size: 16px; text-align: justify;\">根据引渡程序，美国自临时逮捕之日起有60天时间向加提供支持指控的文件。加政府的一个法律团队必须在30天后决定是否引渡。被告可向上诉法院申诉。如不服上诉法院裁定可再上诉到加拿大联邦法院。最终，加拿大司法部长将决定是否把某人引渡到美国。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这些来来回回可能正好赶上美国国会讨论修订后的美加墨自由贸易协定，还将与美中贸易战的停火期重合。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">加拿大贸易部长吉姆·卡尔说：“我们知道未来的发展方向，正在采取必要举措保障这个未来。”他所说的未来在中国。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">另据加拿大《环球邮报》网站12月6日报道，无论加拿大喜欢与否，加拿大现在都成了中美全球支配地位之争的关键角色，而这场争夺正在危险地升级。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">加拿大眼下处于两难境地：不能不冒犯中国人，除非为了安抚中国人而去大大冒犯美国人。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">中美关系处于低谷，这对加拿大来说很糟，对世界来说也很糟。讽刺之处在于，在温哥华逮捕孟晚舟，加拿大出了一把力，让情况变得更糟。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">此外据加拿大《温哥华星报》网站12月8日报道，前驻华大使、现任加拿大艾伯塔大学中国研究所研究员的居伊·圣-雅克说，温哥华一家法院正在审理孟晚舟的保释申请，加拿大身陷两难境地，一边是与美国的引渡条约，另一边是中国的科技巨头。他说，加拿大现在很容易遭到报复。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">圣-雅克说：“我们对中国来说并不是一个非常重要的国家。我担心他们会对我们施加很大压力。”</span></p>', 'articles/cover/20181211/31ed7904c30f41cd33466a533d765ae1.jpg', '2018-12-11 18:25:12', '1', null, null, '2018-12-11 18:22:27', '2018-12-12 11:27:21', null, '0');
