INSERT INTO `references` VALUES ('1', '王毅外长谈中国公民海外安全：对霸凌行径绝不会坐视不管', 'references/ff07c63b1b23805d7a7e41e8937571e7.jpg', 'gregregewrgerger', 'http://www.cpwlx.com', '1', '2018-12-11 17:26:58', '2018-12-11 17:26:58', null, null, '0', '<div class=\"article-content\" style=\"margin-top: 17px; font-family: arial; font-size: 12px;\"><p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">研讨会现场。澎湃新闻记者 于潇清 摄</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">中国国务委员兼外交部长王毅在12月11日的演讲中谈及中国公民海外安全问题时表示，“我们时刻关心每一位在海外中国同胞的安危冷暖，对于任何肆意侵害中国公民正当权益的霸凌行径，中方绝不会坐视不管，将全力中国维护公民的合法权利，还世界一份公道 正义。”</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">2018年12月11日，王毅出席由中国国际问题研究院及中国国际问题研究基金会联合主办的“国际形势新变化与中国外交新征程——2018年国际形势与中国外交研讨会”，并发表主旨演讲。</span></p></div><div class=\"notice\" style=\"margin-top: 30px; border-left: 1px solid rgb(230, 230, 235); background-color: rgb(247, 247, 250); padding: 14.5px 18px; font-family: arial; font-size: 12px;\"><p style=\"margin-bottom: 0px; padding: 0px; font-size: 13px; line-height: 20px; color: rgb(153, 153, 153);\">本文由百家号作者上传并发布，百家号仅提供信息发布平台。文章仅代表作者个人观点，不代表百度立场。未经作者许可，不得转载。</p></div>');
INSERT INTO `references` VALUES ('2', '孟晚舟事件：加拿大在中美间“走钢丝”', 'references/4d2825a2946353a7c535d933f06f7216.jpg', '参考消息网12月10日报道，据美国政治网站12月7日报道，华为首席财务官孟晚舟在温哥华机场被捕，这使加拿大陷入世界两个超级大国紧张的外交局势之中。无论结', 'http://www.cpwlx.com', '1', '2018-12-11 17:29:32', '2018-12-11 17:30:06', null, null, '0', '<p style=\"margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">参考消息网12月10日报道，据美国政治网站12月7日报道，华为首席财务官孟晚舟在温哥华机场被捕，这使加拿大陷入世界两个超级大国紧张的外交局势之中。无论结局如何，特鲁多政府都需要作出激怒哪个超级大国的艰难抉择。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">报道称，从历史经验看，加拿大几乎无疑会支持自己的超级大国邻居。加拿大眼下正要批准与美国和墨西哥达成的一项贸易协定。但与此同时，加拿大也在设法开辟急需的对华贸易新渠道。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">加拿大与美国历史久远的引渡条约规定，当某种犯罪在加拿大也属于非法时，加方将把犯人引渡到美国。但中国坚称孟晚舟什么也没做错，应当被释放。</span></p><div class=\"article-content\" style=\"margin-top: 17px; font-family: arial; font-size: 12px;\"><p style=\"margin-top: 26px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">根据引渡程序，美国自临时逮捕之日起有60天时间向加提供支持指控的文件。加政府的一个法律团队必须在30天后决定是否引渡。被告可向上诉法院申诉。如不服上诉法院裁定可再上诉到加拿大联邦法院。最终，加拿大司法部长将决定是否把某人引渡到美国。<span class=\"bjh-br\"></span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">这些来来回回可能正好赶上美国国会讨论修订后的美加墨自由贸易协定，还将与美中贸易战的停火期重合。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><img src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/TOg0DQN4nhWe9zy8IWBnRYNmqnTTMhhjGdQE4sSh.jpeg\" style=\"width: 640px;\"><span class=\"bjh-p\"><br></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">加拿大贸易部长吉姆·卡尔说：“我们知道未来的发展方向，正在采取必要举措保障这个未来。”他所说的未来在中国。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">另据加拿大《环球邮报》网站12月6日报道，无论加拿大喜欢与否，加拿大现在都成了中美全球支配地位之争的关键角色，而这场争夺正在危险地升级。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">加拿大眼下处于两难境地：不能不冒犯中国人，除非为了安抚中国人而去大大冒犯美国人。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">中美关系处于低谷，这对加拿大来说很糟，对世界来说也很糟。讽刺之处在于，在温哥华逮捕孟晚舟，加拿大出了一把力，让情况变得更糟。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">此外据加拿大《温哥华星报》网站12月8日报道，前驻华大使、现任加拿大艾伯塔大学中国研究所研究员的居伊·圣-雅克说，温哥华一家法院正在审理孟晚舟的保释申请，加拿大身陷两难境地，一边是与美国的引渡条约，另一边是中国的科技巨头。他说，加拿大现在很容易遭到报复。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">圣-雅克说：“我们对中国来说并不是一个非常重要的国家。我担心他们会对我们施加很大压力。”</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">美国打压华为蓄谋已久</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">据美国《华尔街日报》网站12月8日报道，华为公司的首席财务官和继承人遭扣押，这是美国官员十年来努力阻止华为的最新举措，他们认为后者对国家安全和美国在技术创新方面的全球优势构成威胁。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">报道称，现任和前任美国官员说，国会和情报机构中的对华鹰派在2007年左右开始阻止华为的崛起。随着这家中国公司迅速成长为世界最大的信号塔硬件和相关电信设备的制造商，他们把这项行动扩大成特朗普领导下的一场全面进攻。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">美国官员担心中国政府可能会命令华为暗中监视通信或使通信中断，但华为否认了这一指控。这些担忧在今年变得至关重要，因为无线供应商即将把无线通信技术升级到5G，这项技术将使工厂设备和自动驾驶汽车等许多东西能接入互联网。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">报道称，目前的信号塔设备在很大程度上与传输网络中大部分语音和数据流量的“核心”系统隔离。有了5G，信号塔硬件将接管核心系统的任务。这意味着，此类硬件如果被武器化，就可能破坏整个网络。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">美国国会在2012年将华为设备列入黑名单。过去一年，国会中有影响力的对华鹰派与志同道合的国家安全官员联手，从五角大楼、国务院、商务部和联邦通信委员会等美国机构寻求帮助。所有这些机构今年都出台措施，进一步限制华为在美国的业务，并敦促盟国颁布类似禁令。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">另据日本《产经新闻》12月9日报道，应美国要求，加拿大拘押了华为公司首席财务官，在美国主导下发达国家排挤中国高科技企业的动作趋于频繁。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\">特朗普政府考虑把中国高科技产品从美国情报系统网络中全面清除，打算对在“技术冷战”中敌对的中国进一步施压。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify;\"><span class=\"bjh-p\"><span class=\"bjh-br\"></span></span></p></div><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"></span></p><div class=\"notice\" style=\"margin-top: 30px; border-left: 1px solid rgb(230, 230, 235); background-color: rgb(247, 247, 250); padding: 14.5px 18px; font-family: arial; font-size: 12px;\"><p style=\"margin-bottom: 0px; padding: 0px; font-size: 13px; line-height: 20px; color: rgb(153, 153, 153);\">本文由百家号作者上传并发布，百家号仅提供信息发布平台。文章仅代表作者个人观点，不代表百度立场。未经作者许可，不得转载。</p></div>');
INSERT INTO `references` VALUES ('3', '小锐说 ｜ 紧急召见！中国外交部两次出重手！', 'references/414608c3f111c589c95605bf98c6eb3e.jpg', null, 'http://www.cpwlx.com', '1', '2018-12-11 17:31:20', '2018-12-11 17:31:20', null, null, '0', '<p style=\"margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">参考消息网12月10日报道（文/小锐）</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">“一个人一辈子能做成一件事，已经很不简单了。我们这几个把豆腐磨好，磨成好豆腐，你那几个企业好好发豆芽，把豆芽做好……我们13亿人民每个人做好一件事，拼起来就是伟大祖国。”</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这是刚刚过去的周末，微博上很火的一个视频，发言者是华为创始人任正非。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">@央视新闻 在发布上述视频时加了一句话：建设伟大祖国的必由之路，有你有我！</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">关于加拿大拘押华为高管孟晚舟事件，这两天不断发酵，而中国方面亦密集发声。小锐就带你梳理一下，这个周末究竟发生了什么。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">外交部的两次紧急召见</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><img src=\"http://speak.oss-cn-hongkong.aliyuncs.com//articles/20181211/2o5PbGHvpQPGUjTTf3jhfBNmuaNTyx57bKVoowWr.jpeg\" style=\"width: 600px;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\"><br></span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">立即放人！</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\"><span class=\"bjh-strong\" style=\"font-size: 18px; font-weight: 700;\">立即撤销逮捕令！</span></span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">12月8日和9日，是北京今年入冬以来最寒冷的一个周末。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">这两天，中国外交部副部长乐玉成格外忙碌。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">由他出面代表中国政府两次紧急召见驻华大使，后来被媒体纷纷以“重磅”消息密集报道。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">被召见人，则分别是加拿大驻华大使麦家廉和美国驻华大使布兰斯塔德。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">从外交部网站的消息中，小锐发现，在召见两位大使时，乐玉成副部长均提到了下列8个字：严正交涉，强烈抗议。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">在对美加拘押孟晚舟女士事件的定性上，乐玉成副部长两次亦都作出如下表态：“严重侵犯中国公民的合法、正当权益”，“性质极其恶劣”。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">值得注意的是，在中方两次紧急召见的表态中，处处可见强烈的警示意味。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">8日，中方强烈敦促加方立即释放被拘押人员，切实保障当事人的合法、正当权益。否则必将造成严重后果，加方要为此承担全部责任。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">9日，乐玉成要求美方，立即采取措施纠正错误做法，撤销对中国公民的逮捕令。中方将视美方行动作出进一步反应。</span></p><p style=\"margin-top: 22px; margin-bottom: 0px; padding: 0px; font-size: 16px; line-height: 24px; color: rgb(51, 51, 51); text-align: justify; font-family: arial;\"><span class=\"bjh-p\">用词不可谓不重，警告意味不可谓不清晰。</span></p>');
